"Aktuelle Belegung: {0} wahr, {1} falsch": "Τρέχουσα αποτίμηση: {0} αληθής, {1} ψευδής",
"Aktuelle Belegung: {0} falsch, {1} wahr": "Τρέχουσα αποτίμηση: {0} ψευδής, {1} αληθής",
